 156: /// Compute the total number of passwords for a parsed mask.
 157: pub fn mask_password_count(mask: &ParsedMask) -> usize {
 158:     mask.positions.iter().map(|p| p.len()).product()
 159: }
 160: 
 161: struct MaskPasswordGenerator {
 162:     positions: Vec<Vec<u8>>,
 163:     indices: Vec<usize>,
 164:     total: usize,
 165:     generated: usize,
 166:     finished: bool,
 167: }
 168: 
 169: impl MaskPasswordGenerator {
 170:     fn new(mask: ParsedMask) -> Self {
 171:         let total = mask_password_count(&mask);
 172:         let len = mask.positions.len();
 173:         // Convert char positions to u8 once at construction
 174:         let positions = mask
 175:             .positions
 176:             .into_iter()
 177:             .map(|chars| chars.into_iter().map(|c| c as u8).collect())
 178:             .collect();
 179:         Self {
 180:             positions,
 181:             indices: vec![0; len],
 182:             total,
 183:             generated: 0,
 184:             finished: total == 0,
 185:         }
 186:     }
